@startuml

class Center {
  + Name
  + Address
}

class Room {
  + Number
  + MaxCapacity
}

class Person {
  + FirstName
  + FamilyName
  + BirthDate
}

class Trainer extends Person {
  + Diploma
}

class Session {
  + Date
  + StartingHour
}

class GroupSession extends Session {
  + Type
}

class IndividualSession extends Session {
}

Center "1" *-- "1..*" Room

Person "1" -- "*" Session : participates in

Trainer "1" -- "*" GroupSession : supervises

Session "*" -- "1" Room
Session "*" -- "1" Center

@enduml

